exec('import csv,os\nf="virtual_portfolio.csv"; positions=list(csv.DictReader(open(f,encoding="utf-8"))) if os.path.exists(f) else []\nactive=set(x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip())\nrows=[r for r in csv.DictReader(open("signals_history.csv",encoding="utf-8")) if r["ticker"] in active]\nlatest={}\nfor r in rows:\n if r["ticker"] not in latest or r["date"]>latest[r["ticker"]]["date"]: latest[r["ticker"]]=r\ntracked={p["ticker"] for p in positions if p.get("status") in ("OPEN","PENDING")}\nfor p in positions:\n p.setdefault("signal_date",p.get("entry_date","")); p.setdefault("signal_price",p.get("entry_price","")); p.setdefault("entry_type","CLOTURE_J-1_THEORIQUE" if p.get("status")=="OPEN" else "OUVERTURE_J"); p.setdefault("last_price",p.get("entry_price","")); p.setdefault("current_value_eur",p.get("invested_eur","1000")); p.setdefault("pnl_eur","0"); p.setdefault("pnl_pct","0"); p.setdefault("exit_date",""); p.setdefault("exit_price",""); p.setdefault("exit_reason","")\nfor t,r in latest.items():\n if r["signal"]=="ACHAT" and t not in tracked:\n  currency="EUR" if t.endswith((".PA",".AS")) else "USD"; positions.append({"ticker":t,"signal_date":r["date"],"signal_price":r["price"],"entry_date":"","entry_price":"","entry_type":"OUVERTURE_J","currency":currency,"eurusd_entry":"","quantity":"","invested_eur":"1000","target_price":"","stop_price":"","status":"PENDING","last_price":"","current_value_eur":"1000","pnl_eur":"0","pnl_pct":"0","exit_date":"","exit_price":"","exit_reason":""}); print("CANDIDAT EN ATTENTE :",t,"| Signal J-1 :",r["date"],"| Prochain achat virtuel : ouverture du jour J")\nfields=["ticker","signal_date","signal_price","entry_date","entry_price","entry_type","currency","eurusd_entry","quantity","invested_eur","target_price","stop_price","status","last_price","current_value_eur","pnl_eur","pnl_pct","exit_date","exit_price","exit_reason"]\nwith open(f,"w",newline="",encoding="utf-8") as q:\n w=csv.DictWriter(q,fieldnames=fields,extrasaction="ignore"); w.writeheader(); w.writerows(positions)\nprint("Portefeuille prepare pourr les entrees au jour J :",f)')
